INSERT INTO `messages` VALUES (1, '21b9424e-6bda-4c8d-9408-908db7bb89c4', 'user', '发热两天、咳嗽有黄痰、体温 38.7℃', '{\"scene\": \"triage\"}', '2026-10-06 17:13:07');
INSERT INTO `messages` VALUES (2, '21b9424e-6bda-4c8d-9408-908db7bb89c4', 'assistant', '推荐就诊科室：内科\n风险等级：中风险\n建议您到内科进行进一步评估，因为您的发热伴有咳嗽和黄痰，这些症状可能提示有呼吸道感染的可能。\n建议补充信息：您之前是否有过类似症状？ 最近有无接触感冒患者或其他呼吸道疾病患者？\n健康建议：注意休息，多饮水，保持室内空气流通。 避免自行服用多种药物，尤其是抗生素。\n\n以上内容仅用于健康科普和就医参考，不能替代医生诊断、处方或治疗。', '{\"scene\": \"triage\", \"traces\": [{\"agent\": \"RouterAgent\", \"action\": \"场景路由 → 智能分诊\", \"detail\": \"请求显式指定场景\", \"status\": \"ok\", \"duration_ms\": 0}, {\"agent\": \"ContextAgent\", \"action\": \"整理患者上下文与症状线索\", \"detail\": \"症状线索 3 个；本地风险评估=中风险；历史对话 0 条\", \"status\": \"ok\", \"duration_ms\": 2}, {\"agent\": \"RAGAgent\", \"action\": \"本地知识库检索\", \"detail\": \"本地知识库召回 6 条\", \"status\": \"ok\", \"duration_ms\": 0}, {\"agent\": \"ResearchAgent\", \"action\": \"联网检索（未开启）\", \"detail\": \"本次未开启联网增强，跳过联网检索\", \"status\": \"skipped\", \"duration_ms\": 0}, {\"agent\": \"ReasoningAgent\", \"action\": \"结构化医学推理（大模型结构化推理）\", \"detail\": \"推荐科室=内科；风险等级=中风险\", \"status\": \"ok\", \"duration_ms\": 14472}, {\"agent\": \"SafetyAgent\", \"action\": \"医疗合规检查\", \"detail\": \"替换绝对化表达 0 处；剔除处方剂量 0 处；免责声明已追加\", \"status\": \"ok\", \"duration_ms\": 0}], \"degraded\": false, \"risk_level\": \"中风险\", \"recommended_department\": \"内科\"}', '2026-10-06 17:13:21');
INSERT INTO `messages` VALUES (3, '30f3501e-e5a4-47a4-a92d-a7c4daa32caa', 'user', '布洛芬和感冒灵能一起吃吗', '{\"scene\": \"medication\"}', '2026-10-06 17:13:22');
INSERT INTO `messages` VALUES (4, '30f3501e-e5a4-47a4-a92d-a7c4daa32caa', 'assistant', '建议咨询科室：药学门诊\n风险等级：中风险\n布洛芬和感冒灵可能含有重复成分，建议携带当前服用的所有药品清单到药学门诊或咨询药师。\n建议补充信息：您是否有胃病史或肾功能异常？ 您是否正在服用抗凝药物？\n健康建议：注意观察身体反应，如出现不适及时就医。\n\n以上内容仅用于健康科普和就医参考，不能替代医生诊断、处方或治疗。', '{\"scene\": \"medication\", \"traces\": [{\"agent\": \"RouterAgent\", \"action\": \"场景路由 → 用药咨询\", \"detail\": \"请求显式指定场景\", \"status\": \"ok\", \"duration_ms\": 0}, {\"agent\": \"ContextAgent\", \"action\": \"整理患者上下文与症状线索\", \"detail\": \"症状线索 4 个；本地风险评估=低风险；历史对话 0 条\", \"status\": \"ok\", \"duration_ms\": 0}, {\"agent\": \"RAGAgent\", \"action\": \"本地知识库检索\", \"detail\": \"本地知识库召回 6 条\", \"status\": \"ok\", \"duration_ms\": 0}, {\"agent\": \"ResearchAgent\", \"action\": \"联网检索（未开启）\", \"detail\": \"本次未开启联网增强，跳过联网检索\", \"status\": \"skipped\", \"duration_ms\": 0}, {\"agent\": \"ReasoningAgent\", \"action\": \"结构化医学推理（大模型结构化推理）\", \"detail\": \"推荐科室=药学门诊；风险等级=中风险\", \"status\": \"ok\", \"duration_ms\": 4450}, {\"agent\": \"SafetyAgent\", \"action\": \"医疗合规检查\", \"detail\": \"替换绝对化表达 0 处；剔除处方剂量 0 处；免责声明已追加\", \"status\": \"ok\", \"duration_ms\": 0}], \"degraded\": false, \"risk_level\": \"中风险\", \"recommended_department\": \"药学门诊\"}', '2026-10-06 17:13:26');
INSERT INTO `messages` VALUES (5, '0e71b38c-4c26-46c8-9733-c0d234b2ae8b', 'user', '突发剧烈胸痛，呼吸困难，出冷汗', '{\"scene\": \"triage\"}', '2026-10-06 17:13:26');
INSERT INTO `messages` VALUES (6, '0e71b38c-4c26-46c8-9733-c0d234b2ae8b', 'assistant', '推荐就诊科室：急诊科\n风险等级：高风险\n建议立即前往急诊科进行评估和治疗。患者出现剧烈胸痛、呼吸困难及出冷汗等症状，提示可能存在心血管或呼吸系统急症。\n需要警惕的信号：剧烈胸痛、呼吸困难。\n建议补充信息：症状持续多久了？是否在加重？ 是否伴随发热、呕吐等其他症状？ 是否有相关既往病史或正在服用的药物？\n\n以上内容仅用于健康科普和就医参考，不能替代医生诊断、处方或治疗。', '{\"scene\": \"triage\", \"traces\": [{\"agent\": \"RouterAgent\", \"action\": \"场景路由 → 智能分诊\", \"detail\": \"请求显式指定场景\", \"status\": \"ok\", \"duration_ms\": 0}, {\"agent\": \"ContextAgent\", \"action\": \"整理患者上下文与症状线索\", \"detail\": \"症状线索 2 个；本地风险评估=高风险；历史对话 0 条\", \"status\": \"ok\", \"duration_ms\": 0}, {\"agent\": \"RAGAgent\", \"action\": \"本地知识库检索\", \"detail\": \"本地知识库召回 6 条\", \"status\": \"ok\", \"duration_ms\": 0}, {\"agent\": \"ResearchAgent\", \"action\": \"联网检索（未开启）\", \"detail\": \"本次未开启联网增强，跳过联网检索\", \"status\": \"skipped\", \"duration_ms\": 0}, {\"agent\": \"ReasoningAgent\", \"action\": \"结构化医学推理（大模型结构化推理）\", \"detail\": \"推荐科室=急诊科；风险等级=高风险\", \"status\": \"ok\", \"duration_ms\": 4490}, {\"agent\": \"SafetyAgent\", \"action\": \"医疗合规检查\", \"detail\": \"替换绝对化表达 0 处；剔除处方剂量 0 处；免责声明已追加\", \"status\": \"ok\", \"duration_ms\": 0}], \"degraded\": false, \"risk_level\": \"高风险\", \"recommended_department\": \"急诊科\"}', '2026-10-06 17:13:31');
INSERT INTO `messages` VALUES (7, '60f6255b-b398-43ac-aa7f-7a17083dd628', 'user', '发热两天、咳嗽有黄痰、体温 38.7℃', '{\"scene\": \"triage\"}', '2026-10-06 17:15:04');
INSERT INTO `messages` VALUES (8, '60f6255b-b398-43ac-aa7f-7a17083dd628', 'assistant', '推荐就诊科室：内科\n风险等级：中风险\n建议您到内科进行进一步评估，发热伴有咳嗽黄痰提示可能存在呼吸道感染。\n建议补充信息：您最近是否有服用任何药物？ 您的饮食和睡眠情况如何？\n健康建议：保持充分休息，多饮水，注意观察体温变化。 避免自行使用多种药物治疗，如有需要请咨询医生。\n\n以上内容仅用于健康科普和就医参考，不能替代医生诊断、处方或治疗。', '{\"scene\": \"triage\", \"traces\": [{\"agent\": \"RouterAgent\", \"action\": \"场景路由 → 智能分诊\", \"detail\": \"请求显式指定场景\", \"status\": \"ok\", \"duration_ms\": 0}, {\"agent\": \"ContextAgent\", \"action\": \"整理患者上下文与症状线索\", \"detail\": \"症状线索 3 个；本地风险评估=中风险；历史对话 0 条\", \"status\": \"ok\", \"duration_ms\": 2}, {\"agent\": \"RAGAgent\", \"action\": \"本地知识库检索\", \"detail\": \"本地知识库召回 6 条\", \"status\": \"ok\", \"duration_ms\": 0}, {\"agent\": \"ResearchAgent\", \"action\": \"联网检索（未开启）\", \"detail\": \"本次未开启联网增强，跳过联网检索\", \"status\": \"skipped\", \"duration_ms\": 0}, {\"agent\": \"ReasoningAgent\", \"action\": \"结构化医学推理（大模型结构化推理）\", \"detail\": \"推荐科室=内科；风险等级=中风险\", \"status\": \"ok\", \"duration_ms\": 7390}, {\"agent\": \"SafetyAgent\", \"action\": \"医疗合规检查\", \"detail\": \"替换绝对化表达 0 处；剔除处方剂量 0 处；免责声明已追加\", \"status\": \"ok\", \"duration_ms\": 0}], \"degraded\": false, \"risk_level\": \"中风险\", \"recommended_department\": \"内科\"}', '2026-10-06 17:15:12');
INSERT INTO `messages` VALUES (9, 'bc093391-9543-4f9b-bc1b-6c6f159b7817', 'user', '头痛三天了，晚上睡不着', '{\"scene\": \"consultation\"}', '2026-10-06 17:15:12');
INSERT INTO `messages` VALUES (10, 'bc093391-9543-4f9b-bc1b-6c6f159b7817', 'assistant', '推荐就诊科室：内科\n风险等级：中风险\n建议您到内科进行评估，因为您的头痛已经持续了三天，并且影响到了睡眠质量。\n建议补充信息：您是否有其他伴随症状？如恶心、呕吐、视力模糊等。 最近是否测量过血压？\n健康建议：可以先尝试使用非处方止痛药缓解疼痛，但不要超过推荐剂量。 注意休息，避免过度劳累和精神紧张。\n\n以上内容仅用于健康科普和就医参考，不能替代医生诊断、处方或治疗。', '{\"scene\": \"consultation\", \"traces\": [{\"agent\": \"RouterAgent\", \"action\": \"场景路由 → 线上问诊\", \"detail\": \"请求显式指定场景\", \"status\": \"ok\", \"duration_ms\": 0}, {\"agent\": \"ContextAgent\", \"action\": \"整理患者上下文与症状线索\", \"detail\": \"症状线索 1 个；本地风险评估=中风险；历史对话 0 条\", \"status\": \"ok\", \"duration_ms\": 0}, {\"agent\": \"RAGAgent\", \"action\": \"本地知识库检索\", \"detail\": \"本地知识库召回 6 条\", \"status\": \"ok\", \"duration_ms\": 0}, {\"agent\": \"ResearchAgent\", \"action\": \"联网检索（未开启）\", \"detail\": \"本次未开启联网增强，跳过联网检索\", \"status\": \"skipped\", \"duration_ms\": 0}, {\"agent\": \"ReasoningAgent\", \"action\": \"结构化医学推理（大模型结构化推理）\", \"detail\": \"推荐科室=内科；风险等级=中风险\", \"status\": \"ok\", \"duration_ms\": 6003}, {\"agent\": \"SafetyAgent\", \"action\": \"医疗合规检查\", \"detail\": \"替换绝对化表达 0 处；剔除处方剂量 0 处；免责声明已追加\", \"status\": \"ok\", \"duration_ms\": 0}], \"degraded\": false, \"risk_level\": \"中风险\", \"recommended_department\": \"内科\"}', '2026-10-06 17:15:18');
